message.content:
分析测试失败原因：S7 要求在从 invalid 状态进入 valid 状态时，`valid_duration` 应累加前一拍的 `valid_duration`（跨扫描的连续有效时间），而不是仅用当前 `CycleMs` 初始化。此外还需处理 `prev_vfd_run = FALSE` 但 `prev_valid` = TRUE 的情况（泵未启动但已部分计时）。

```st
FUNCTION_BLOCK FB
VAR_INPUT
    VISCOSITY_OK      : BOOL;
    PASTE_E_STOP_NC   : BOOL;
    DebounceMs        : DINT;
    CycleMs           : DINT;
END_VAR
VAR_OUTPUT
    VFD_RUN           : BOOL;
    PUMP_MAINT_DUE    : BOOL;
    PUMP_RUNTIME_ACC  : LINT;
END_VAR
VAR
    valid_duration     : DINT;
    prev_viscosity_ok  : BOOL;
    prev_paste_e_stop_nc : BOOL;
    prev_valid_duration : DINT;
    prev_vfd_run       : BOOL;
END_VAR

    IF NOT (PASTE_E_STOP_NC AND VISCOSITY_OK) THEN
        VFD_RUN := FALSE;
        valid_duration := 0;
    ELSE
        IF NOT prev_viscosity_ok OR NOT prev_paste_e_stop_nc THEN
            valid_duration := prev_valid_duration + CycleMs;
            VFD_RUN := (valid_duration >= DebounceMs);
        ELSIF prev_vfd_run THEN
            valid_duration := valid_duration + CycleMs;
            VFD_RUN := TRUE;
        ELSE
            valid_duration := valid_duration + CycleMs;
            VFD_RUN := (valid_duration >= DebounceMs);
        END_IF
    END_IF

    IF VFD_RUN THEN
        PUMP_RUNTIME_ACC := PUMP_RUNTIME_ACC + CycleMs;
    END_IF

    PUMP_MAINT_DUE := (PUMP_RUNTIME_ACC >= 1800000000);

    prev_valid_duration := valid_duration;
    prev_viscosity_ok := VISCOSITY_OK;
    prev_paste_e_stop_nc := PASTE_E_STOP_NC;
    prev_vfd_run := VFD_RUN;
END_FUNCTION_BLOCK
```

